from __future__ import print_function

import logging

from ta_ue_plugin_android.uepc.datatransfer.data_transfers_manager import DataTransfersManager
from ta_ue_plugin_android.uepc.ue_pc_logger import LoggerAdapter4EmptyExtra
from ta_ue_plugin_android.uepc.ue_pool_on_server import UePool2WithTakeCareThread
from ta_ue_plugin_android.uepc.uepool_backends import ComplexUePool2Backed


class UePoolController(object):
    """Class representing UE pool on UEPC and handling creation of UEs"""

    def __init__(self, ssh_manager):
        """Basic initialization."""
        raw_logger = logging.getLogger("ute_ue.uepc")
        self.logger = LoggerAdapter4EmptyExtra(raw_logger, {'area': 'UEPOOLCTRL'})
        self.ssh_manager = ssh_manager
        self.pool = self._create_ue_pool()
        self.data_transfers_manager = DataTransfersManager(self.pool, self.ssh_manager)

    def _create_ue_pool(self):
        backend = self._new_complex_ue_pool_backend()
        pool = self._new_ue_pool(backend)
        return pool

    def _new_complex_ue_pool_backend(self):
        return ComplexUePool2Backed(self.ssh_manager)

    def _new_ue_pool(self, backend):
        return UePool2WithTakeCareThread(backend)

    def reserve_ue(self, ue_sn):
        """
        reserve_ue
        :param ue_sn:
        """
        self.pool.reserve_ue(ue_sn)

    def unreserve_ue(self, ue_sn):
        """
        unreserve_ue
        :param ue_sn:
        """
        # TODO: in future: unreserve after timeout
        self.pool.unreserve_ue(ue_sn)

    def keep_reservation(self, ue_sn):
        """
        Keeps the reservation on UE. If you will not calling this method, reservation will expire.
        :param ue_sn: serial number of UE
        """
        self.pool.keep_reservation(ue_sn)

    def start_data_transfer(self, ue_sn, dt_name, dt_config):
        """Proxes method to data_transfers_manage"""
        return self.data_transfers_manager.start_data_transfer(ue_sn, dt_name, dt_config)

    def add_to_force_stopped(self, ue_sn, dt_name):
        """Proxes method to data_transfers_manage"""
        return self.data_transfers_manager.add_to_force_stopped(ue_sn, dt_name)

    def is_data_transfer_finish(self, ue_sn, dt_name):
        """Proxes method to data_transfers_manager"""
        return self.data_transfers_manager.is_data_transfer_finish(ue_sn, dt_name)

    def is_data_transfer_started(self, ue_sn, dt_name):
        """Proxes method to data_transfers_manager"""
        return self.data_transfers_manager.is_data_transfer_started(ue_sn, dt_name)

    def check_data_transfer(self, ue_sn, dt_name):
        """Checks if iperf data transfer is progressing on client and server"""
        return self.data_transfers_manager.check_data_transfer(ue_sn, dt_name)

    def count_avg_throughput(self, ue_sn, dt_name, omit=0, end=0, tput_collection_src="iperf"):
        """Proxes method to data_transfers_manager"""
        return self.data_transfers_manager.count_avg_throughput(ue_sn, dt_name, omit, end, tput_collection_src)

    def get_datagram_loss(self, ue_sn, dt_name):
        """Proxes method to data_transfers_manager"""
        return self.data_transfers_manager.get_datagram_loss(ue_sn, dt_name)

    def get_dt_reports(self, ue_sn, dt_name, tail=0):
        """Proxes method to data_transfers_manager"""
        return self.data_transfers_manager.get_dt_reports(ue_sn, dt_name, tail)

    def get_data_transfer_statistics(self, ue_sn, dt_name):
        """Return string with dt statistics: avg,min,max;comma-delimited list of bits/s for all intervals"""
        return self.data_transfers_manager.get_data_transfer_statistics(dt_name, ue_sn)

    def release_dt_name(self, ue_sn, dt_name, force_close=False):
        """Proxes method to data_transfers_manager"""
        return self.data_transfers_manager.release_dt_name(ue_sn, dt_name, force_close)

    def close_dt(self, ue_sn, dt_name, force_close=False):
        """Proxes method to data_transfers_manager"""
        return self.data_transfers_manager.close_dt(ue_sn, dt_name, force_close)

    def close_data_transfers_manager(self):
        """Proxes method to data_transfers_manager"""
        return self.data_transfers_manager.close_data_transfers_manager()

    def _is_callable(self, obj):
        return hasattr(obj, '__call__')

    def get_adb_path(self):
        """
        get_adb_path
        :return:
        """
        return self.pool.get_adb_path()

    def shutdown_pool(self):
        """
        Releases resources used by this pool.
        For examples, kills all threads.
        """
        self.data_transfers_manager.close_data_transfers_manager()
        self.pool.shutdown()
